const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey=()=>`SafetyV27:Draft:${currentId}`;

function renderPersonField(field){
  return `<label class="field ${field.full?'full':''}">
    <span>${esc(field.label)}${field.required?' *':''}</span>
    <select data-key="${esc(field.key)}">
      <option value="">선택하세요</option>
      ${TEAM_MEMBERS.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}
    </select>
  </label>`;
}

function renderFields(section){
  const cols=Number(section.columns)||2;
  return `<div class="field-grid field-grid-${cols}">${(section.fields||[]).map(field=>{
    if(field.input==='person') return renderPersonField(field);
    if(field.input==='textarea'){
    const largePermit=(currentId==='hot-work-permit' && ['work','risk','measure'].includes(field.key)) || field.largePermitText===true;
    const largeLog=field.largeLogText===true;
    const textareaClass=[largePermit?'hot-large-textarea':'',largeLog?'safety-log-textarea':''].filter(Boolean).join(' ');
    return `<label class="field ${field.full?'full':''}"><span>${esc(field.label)}${field.required?' *':''}</span><textarea class="${textareaClass}" data-key="${esc(field.key)}" data-has-default="${field.default?'1':'0'}" placeholder="${esc(field.placeholder||'')}">${esc(field.default||'')}</textarea></label>`;
  }
    if(field.input==='select') return `<label class="field ${field.full?'full':''}"><span>${esc(field.label)}${field.required?' *':''}</span><select data-key="${esc(field.key)}">${(field.options||[]).map(x=>`<option>${esc(x)}</option>`).join('')}</select></label>`;
    return `<label class="field ${field.full?'full':''}"><span>${esc(field.label)}${field.required?' *':''}</span><input data-key="${esc(field.key)}" data-has-default="${field.default?'1':'0'}" type="${esc(field.input||'text')}" value="${esc(field.default||'')}" placeholder="${esc(field.placeholder||'')}" ${field.readonly?'readonly':''}></label>`;
  }).join('')}</div>`;
}
function renderChecklist(section){return `<div class="check-list">${(section.items||[]).map(item=>`<label class="check"><input data-key="${esc(item.key)}" type="checkbox"><span><b>${esc(item.label)}</b><small>${esc(item.help||'')}</small></span></label>`).join('')}</div>`;}
function renderFixedText(section){
  return `<div class="fixed-text">${(section.lines||[]).map(line=>`<div class="fixed-line"><span class="fixed-bullet">•</span><span>${esc(line)}</span></div>`).join('')}</div>`;
}
function renderPhotos(section,index){
  const count=Math.max(1,Number(section.count)||2);
  return `<div class="photo-grid">${Array.from({length:count},(_,i)=>`
    <div class="photo-slot" data-photo-slot="${i}">
      <input type="file" accept="image/*" data-photo-input="${i}">
      <label class="photo-label" for="photo_${index}_${i}">
        <span><b>사진 ${i+1}</b>클릭해서 교육사진을 선택하세요.</span>
      </label>
      <img class="photo-preview" data-photo-preview="${i}" alt="교육사진 ${i+1}">
      <div class="photo-actions">
        <button type="button" data-photo-change="${i}">사진 변경</button>
        <button type="button" data-photo-remove="${i}">삭제</button>
      </div>
    </div>`).join('')}</div>`;
}
function renderTable(section,sectionIndex){
 const cols=section.columns||[],rows=Math.max(1,Number(section.rows)||1);
 return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:rows},(_,r)=>`<tr>${cols.map((_,c)=>`<td><input data-key="table_${sectionIndex}_${r}_${c}" aria-label="${esc(cols[c])} ${r+1}"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}


function numberValue(key){
  const el=paper.querySelector(`[data-key="${key}"]`);
  if(!el) return 0;
  const n=Number(el.value.replace(/,/g,''));
  return Number.isFinite(n)?n:0;
}

function setCalculatedValue(key,value){
  const el=paper.querySelector(`[data-key="${key}"]`);
  if(!el) return;
  el.value=String(value);
}

function updateSafetyLogTotals(){
  if(currentId!=='safety-education-log') return;

  const staffTotal=
    numberValue('staff_employee')+
    numberValue('staff_worker')+
    numberValue('staff_direct')+
    numberValue('staff_outsource');
  setCalculatedValue('staff_total',staffTotal);

  const accidentTotal=
    numberValue('human_accident')+
    numberValue('property_accident');
  setCalculatedValue('accident_total',accidentTotal);
}

function wireSafetyLogTotals(){
  if(currentId!=='safety-education-log') return;

  const sourceKeys=[
    'staff_employee','staff_worker','staff_direct','staff_outsource',
    'human_accident','property_accident'
  ];

  sourceKeys.forEach(key=>{
    const el=paper.querySelector(`[data-key="${key}"]`);
    if(!el) return;
    const update=()=>{
      updateSafetyLogTotals();
      saveDraft();
    };
    el.addEventListener('input',update);
    el.addEventListener('change',update);
  });

  ['staff_total','accident_total'].forEach(key=>{
    const el=paper.querySelector(`[data-key="${key}"]`);
    if(el){
      el.readOnly=true;
      el.tabIndex=-1;
    }
  });

  updateSafetyLogTotals();
}

