function findSafetyRiskItem(trade){
  const text=(trade||'').trim().toLowerCase();
  if(!text) return null;
  return SAFETY_RISK_LIBRARY.find(item=>item.keys.some(k=>text.includes(k.toLowerCase())))||null;
}

function suggestSafetyRisk(trade){
  const found=findSafetyRiskItem(trade);
  return found ? found.risk : '작업구역 내 자재·공구로 인한 걸림·넘어짐 및 낙하·맞음, 작업방법 또는 장비 사용 부주의에 따른 협착·베임 등의 위험';
}

function suggestSafetyAction(trade){
  const found=findSafetyRiskItem(trade);
  return found ? found.action : '작업 전 작업방법과 장비 상태를 점검하고 작업구역을 정리·통제한다. 해당 작업에 적합한 개인보호구를 착용하며 자재·공구의 낙하·전도 및 작업자 협착·베임 위험을 예방할 수 있도록 안전조치를 실시한다.';
}

function safetyRiskRowCount(){
  const raw=localStorage.getItem(`SafetyV27:RiskRows:${currentId}`);
  return Math.max(1,Number(raw)||1);
}

function riskPersonOptions(){
  return `<option value="">선택하세요</option>${TEAM_MEMBERS.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}`;
}

function renderRiskRows(section,sectionIndex){
  const count=safetyRiskRowCount();
  const rows=Array.from({length:count},(_,r)=>`
    <div class="risk-row" data-risk-row="${r}">
      <label class="risk-row-field">
        <span>공종명</span>
        <input type="text" data-key="risk_${sectionIndex}_${r}_trade" data-risk-trade="${r}" placeholder="예: 금속공사">
      </label>
      <label class="risk-row-field">
        <span>위험사항</span>
        <textarea data-key="risk_${sectionIndex}_${r}_hazard" data-risk-hazard="${r}" placeholder="공종명을 입력하면 자동 추천됩니다."></textarea>
        <small class="risk-auto-note">자동 추천 후 직접 수정 가능</small>
      </label>
      <label class="risk-row-field">
        <span>담당자</span>
        <select data-key="risk_${sectionIndex}_${r}_manager">${riskPersonOptions()}</select>
      </label>
      <label class="risk-row-field">
        <span>내용</span>
        <textarea data-key="risk_${sectionIndex}_${r}_content" placeholder="조치내용 또는 관리내용 입력"></textarea>
      </label>
      <button type="button" class="risk-remove" data-risk-remove="${r}" title="행 삭제">×</button>
    </div>`).join('');

  return `<div class="risk-rows-wrap" data-risk-section="${sectionIndex}">${rows}</div>
    <button type="button" class="risk-add" data-risk-add="${sectionIndex}">+ 공정 추가</button>`;
}

function addSafetyRiskRow(sectionIndex){
  const count=safetyRiskRowCount()+1;
  localStorage.setItem(`SafetyV27:RiskRows:${currentId}`,String(count));
  const current=values();
  localStorage.setItem(storageKey(),JSON.stringify(current));
  render();
  status.textContent='공정 작성칸을 추가했습니다.';
}

function removeSafetyRiskRow(rowIndex){
  const count=safetyRiskRowCount();
  if(count<=1) return;
  const rows=[];
  for(let r=0;r<count;r++){
    if(r===rowIndex) continue;
    rows.push({
      trade:paper.querySelector(`[data-key="risk_8_${r}_trade"]`)?.value||'',
      hazard:paper.querySelector(`[data-key="risk_8_${r}_hazard"]`)?.value||'',
      manager:paper.querySelector(`[data-key="risk_8_${r}_manager"]`)?.value||'',
      content:paper.querySelector(`[data-key="risk_8_${r}_content"]`)?.value||''
    });
  }
  localStorage.setItem(`SafetyV27:RiskRows:${currentId}`,String(rows.length));
  const draft=JSON.parse(localStorage.getItem(storageKey())||'{}');
  Object.keys(draft).filter(k=>k.startsWith('risk_8_')).forEach(k=>delete draft[k]);
  rows.forEach((row,r)=>{
    draft[`risk_8_${r}_trade`]=row.trade;
    draft[`risk_8_${r}_hazard`]=row.hazard;
    draft[`risk_8_${r}_manager`]=row.manager;
    draft[`risk_8_${r}_content`]=row.content;
  });
  localStorage.setItem(storageKey(),JSON.stringify(draft));
  render();
  status.textContent='공정 작성칸을 삭제했습니다.';
}

function wireSafetyRiskRows(){
  if(currentId!=='safety-education-log') return;

  paper.querySelectorAll('[data-risk-trade]').forEach(input=>{
    const r=input.dataset.riskTrade;
    const hazard=paper.querySelector(`[data-risk-hazard="${r}"]`);
    const content=paper.querySelector(`[data-key="risk_8_${r}_content"]`);
    const apply=()=>{
      if(!hazard) return;

      const riskSuggestion=suggestSafetyRisk(input.value);
      const previousRiskAuto=hazard.dataset.autoValue||'';
      if(!hazard.value.trim() || hazard.value===previousRiskAuto){
        hazard.value=riskSuggestion;
        hazard.dataset.autoValue=riskSuggestion;
      }

      if(content){
        const actionSuggestion=suggestSafetyAction(input.value);
        const previousActionAuto=content.dataset.autoValue||'';
        if(!content.value.trim() || content.value===previousActionAuto){
          content.value=actionSuggestion;
          content.dataset.autoValue=actionSuggestion;
        }
      }

      saveDraft();
    };
    input.addEventListener('change',apply);
    input.addEventListener('blur',apply);
  });

  paper.querySelectorAll('[data-risk-add]').forEach(btn=>{
    btn.addEventListener('click',()=>addSafetyRiskRow(Number(btn.dataset.riskAdd)));
  });

  paper.querySelectorAll('[data-risk-remove]').forEach(btn=>{
    btn.addEventListener('click',()=>removeSafetyRiskRow(Number(btn.dataset.riskRemove)));
  });
}

function renderSection(section,index){
 let body='';
 if(section.type==='fields') body=renderFields(section);
 else if(section.type==='checklist') body=renderChecklist(section);
 else if(section.type==='table') body=renderTable(section,index);
 else if(section.type==='riskRows') body=renderRiskRows(section,index);
 else if(section.type==='fixedtext') body=renderFixedText(section);
 else if(section.type==='photos') body=renderPhotos(section,index);
 else body='<div class="empty-state">내용을 입력하세요.</div>';
 return `<section class="section"><div class="section-title"><span class="section-no">${index+1}</span><h3>${esc(section.title)}</h3></div>${section.note?`<p class="section-note">${esc(section.note)}</p>`:''}${body}</section>`;
}


