function scField(key,label,input='text',opts={}){
  const full=opts.full?' full':'';
  const ro=opts.readonly?' readonly':'';
  const value=opts.value!=null?` value="${esc(opts.value)}"`:'';
  const ph=opts.placeholder?` placeholder="${esc(opts.placeholder)}"`:'';
  if(input==='select'){
    return `<label class="sc-field${full}"><span>${esc(label)}</span><select data-key="${esc(key)}">${(opts.options||[]).map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`;
  }
  return `<label class="sc-field${full}"><span>${esc(label)}</span><input data-key="${esc(key)}" type="${esc(input)}"${value}${ph}${ro}></label>`;
}


