function safetyCostDetailRowIds(catId){
  const key=`SafetyV27:CostDetailRows:${catId}`;
  try{
    const saved=JSON.parse(localStorage.getItem(key)||'null');
    if(Array.isArray(saved) && saved.length) return saved;
  }catch{}
  const defaults=Array.from({length:SAFETY_COST_DETAIL_DEFAULT_ROWS},(_,i)=>i);
  localStorage.setItem(key,JSON.stringify(defaults));
  return defaults;
}

function saveSafetyCostDetailRowIds(catId,ids){
  localStorage.setItem(`SafetyV27:CostDetailRows:${catId}`,JSON.stringify(ids));
}

function nextSafetyCostDetailRowId(catId){
  const ids=safetyCostDetailRowIds(catId);
  return ids.length?Math.max(...ids.map(Number))+1:0;
}

function addSafetyCostDetailRow(catId){
  if(currentId!=='safety-cost-statement') return;
  const draft=values();
  localStorage.setItem(storageKey(),JSON.stringify(draft));

  const ids=safetyCostDetailRowIds(catId);
  ids.push(nextSafetyCostDetailRowId(catId));
  saveSafetyCostDetailRowIds(catId,ids);

  rerenderSafetyCostKeepPosition(2);
  status.textContent='항목별 사용내역 작성칸을 추가했습니다.';
}

function deleteSafetyCostDetailRow(catId,rowId){
  if(currentId!=='safety-cost-statement') return;

  const ids=safetyCostDetailRowIds(catId).filter(id=>Number(id)!==Number(rowId));
  if(ids.length===0){
    status.textContent='각 항목에는 최소 1개의 작성칸이 필요합니다.';
    return;
  }

  const draft=values();
  [
    'date','desc','price','unit','qty','amount','rate'
  ].forEach(suffix=>delete draft[`sc_d_${catId}_${rowId}_${suffix}`]);

  localStorage.setItem(storageKey(),JSON.stringify(draft));
  saveSafetyCostDetailRowIds(catId,ids);

  rerenderSafetyCostKeepPosition(2);
  status.textContent='항목별 사용내역 작성칸을 삭제했습니다.';
}

