function safetyCostSlotIds(type){
  const key=`SafetyV27:CostSlots:${type}`;
  try{
    const saved=JSON.parse(localStorage.getItem(key)||'null');
    if(Array.isArray(saved) && saved.length){
      const minimum=type==='photo'?4:type==='statement'?2:1;
      while(saved.length<minimum) saved.push(saved.length?Math.max(...saved)+1:0);
      localStorage.setItem(key,JSON.stringify(saved));
      return saved;
    }
  }catch{}
  const defaults=type==='tax'?[0]:type==='photo'?[0,1,2,3]:[0,1];
  localStorage.setItem(key,JSON.stringify(defaults));
  return defaults;
}

function saveSafetyCostSlotIds(type,ids){
  localStorage.setItem(`SafetyV27:CostSlots:${type}`,JSON.stringify(ids));
}

function nextSafetyCostSlotId(type){
  const ids=safetyCostSlotIds(type);
  return ids.length?Math.max(...ids)+1:0;
}

function addSafetyCostSlot(type){
  if(currentId!=='safety-cost-statement') return;
  const ids=safetyCostSlotIds(type);
  ids.push(nextSafetyCostSlotId(type));
  saveSafetyCostSlotIds(type,ids);
  const draft=values();
  localStorage.setItem(storageKey(),JSON.stringify(draft));
  rerenderSafetyCostKeepPosition(safetyCostPage);
  status.textContent='첨부 칸을 추가했습니다.';
}

function deleteSafetyCostSlot(type,slotId){
  if(currentId!=='safety-cost-statement') return;
  const ids=safetyCostSlotIds(type).filter(id=>Number(id)!==Number(slotId));
  if(ids.length===0){
    status.textContent='첨부 칸은 최소 1개 이상 남겨야 합니다.';
    return;
  }
  saveSafetyCostSlotIds(type,ids);
  localStorage.removeItem(safetyCostImageKey(`${type}_${slotId}`));

  if(type==='photo'){
    const draft=JSON.parse(localStorage.getItem(storageKey())||'{}');
    delete draft[`sc_photo_desc_${slotId}`];
    localStorage.setItem(storageKey(),JSON.stringify(draft));
  }else{
    const draft=values();
    localStorage.setItem(storageKey(),JSON.stringify(draft));
  }

  rerenderSafetyCostKeepPosition(safetyCostPage);
  status.textContent='첨부 칸을 삭제했습니다.';
}

