function saveDraft(){try{localStorage.setItem(storageKey(),JSON.stringify(values()));status.textContent='임시 저장됨 · 현재 브라우저에 저장되었습니다.';}catch{status.textContent='저장공간 부족 · 입력은 화면에 유지됩니다. JSON 백업을 내려받아 주세요.';}}
function restoreDraft(){
 let draft={};try{draft=JSON.parse(localStorage.getItem(storageKey())||'{}')}catch{}
 paper.querySelectorAll('[data-key]').forEach(el=>{
  if(!(el.dataset.key in draft)) return;
  if(el.type==='checkbox'){
    el.checked=Boolean(draft[el.dataset.key]);
    return;
  }
  const saved=draft[el.dataset.key];
  const hasDefault=el.dataset.hasDefault==='1';
  if(hasDefault && (saved==='' || saved==null)) return;
  if(el.tagName==='SELECT' && saved && ![...el.options].some(o=>o.value===saved))el.add(new Option(saved,saved));
  el.value=el.type==='number'?String(saved).replace(/,/g,''):saved;
 });
}

function photoStorageKey(index){return `SafetyV27:Photo:${currentId}:${index}`;}

function compressImage(file,maxWidth=1400,quality=.82){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=reject;
    reader.onload=()=>{
      const img=new Image();
      img.onerror=reject;
      img.onload=()=>{
        let width=img.width,height=img.height;
        if(width>maxWidth){
          height=Math.round(height*(maxWidth/width));
          width=maxWidth;
        }
        const canvas=document.createElement('canvas');
        canvas.width=width; canvas.height=height;
        const ctx=canvas.getContext('2d');
        ctx.drawImage(img,0,0,width,height);
        resolve(canvas.toDataURL('image/jpeg',quality));
      };
      img.src=reader.result;
    };
    reader.readAsDataURL(file);
  });
}

