function downloadStaticOutput(kind){
  const files=OUTPUT_FILES[currentId];
  if(!files){
    status.textContent='이 서류는 아직 Excel/PDF 자동출력 연동 준비중입니다.';
    return;
  }
  const filename=kind==='excel'?files.excel:files.pdf;
  if(!filename){
    status.textContent=kind==='pdf'?'PDF 자동출력은 최종 서버 연동 단계에서 연결합니다.':'Excel 출력 연동 준비중입니다.';
    return;
  }
  const a=document.createElement('a');
  if(kind==='excel' && files.embeddedExcel && EMBEDDED_XLSX[currentId]){
    const raw=atob(EMBEDDED_XLSX[currentId]);
    const bytes=new Uint8Array(raw.length);
    for(let i=0;i<raw.length;i++) bytes[i]=raw.charCodeAt(i);
    const blob=new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
    const url=URL.createObjectURL(blob);
    a.href=url;
    a.download=filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1000);
    status.textContent=`${DOC_MAP[currentId]?.title||'서류'} Excel 원본을 다운로드했습니다. 현재 입력값 자동주입은 최종 출력 연동 단계에서 연결합니다.`;
    return;
  }
  a.href=encodeURI(filename);
  a.download=filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  status.textContent=`${kind==='excel'?'Excel':'PDF'} 출력파일 다운로드를 시작했습니다.`;
}


