function syncMsdsEducationPeriod(){
  if(currentId!=='msds-education-result') return;
  const writeDate=paper.querySelector('[data-key="writeDate"]');
  const educationPeriod=paper.querySelector('[data-key="educationPeriod"]');
  if(!writeDate || !educationPeriod) return;

  const raw=(writeDate.value||'').trim();
  let dateText='';
  if(raw){
    const parts=raw.split('-');
    if(parts.length===3){
      dateText=`${parts[0]}.${parts[1]}.${parts[2]}`;
    }else{
      dateText=raw.replace(/-/g,'.');
    }
  }
  educationPeriod.value=dateText ? `${dateText} 07:30 ~ 08:00` : '07:30 ~ 08:00';
}

