 const d=DOC_MAP[currentId],payload={schemaVersion:2,documentId:d.id,category:d.category,title:d.title,values:values(),attachments:Object.fromEntries(storageKeys().filter(k=>k.startsWith('SafetyV27:Photo:'+currentId+':')||(currentId==='safety-cost-statement'&&k.startsWith('SafetyV27:Cost'))).map(k=>[k,localStorage.getItem(k)]))};
