function printSafetyCost(printAll=false){
  const classes=['printing-safety','safety-cost-print'];
  if(printAll) classes.push('safety-cost-print-all');
  document.body.classList.add(...classes);
  const cleanup=()=>document.body.classList.remove('printing-safety','safety-cost-print','safety-cost-print-all');
  window.addEventListener('afterprint',cleanup,{once:true});
  try{window.print();}catch(error){cleanup();throw error}
}
